{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']

    # Build list of edges with mutual reachability weight
    edges = []
    for u, v, d in distances:
        w = max(core[u], core[v], d)
        # canonicalize endpoints: lexicographic order
        if u > v:
            u, v = v, u
        edges.append((w, u, v))

    # Sort by weight, then u, then v
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    n = len(nodes)
    if n == 0:
        return {'mst_edges': [], 'total_weight': 0.0}
    if n == 1:
        return {'mst_edges': [], 'total_weight': 0.0}

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    edges_used = 0
    target = n - 1

    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            edges_used += 1
            if edges_used == target:
                break

    if edges_used != target:
        raise ValueError("Graph is disconnected; cannot form a spanning tree.")

    return {'mst_edges': mst_edges, 'total_weight': total_weight}"
}
